const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const start = '2020-01-08';
    const end = '2020-01-16'; // end-exclusive, covers Jan 8–15 inclusive
    const scale = 5000; // km-scale appropriate for CHIRPS
    const thresholdMM = 76.2; // 3 inches in mm

    // Build region: FAO GAUL Level1 (Iran, Sistan-Baluchestan). Fallback: rectangle approx.
    const gaul = ee.FeatureCollection('FAO/GAUL/2015/level1');
    const iranAdm1 = gaul
      .filter(ee.Filter.stringContains('ADM0_NAME', 'Iran'))
      .filter(ee.Filter.stringContains('ADM1_NAME', 'Sistan'));
    const admCount = await iranAdm1.size().getInfo();
    let region = null;
    let regionNote = '';
    if (admCount && admCount > 0) {
      region = ee.Feature(iranAdm1.first()).geometry();
      regionNote = 'Region: GAUL Level1 Sistan-Baluchestan';
    } else {
      // Fallback approximate bounds for Sistan-Baluchestan
      region = ee.Geometry.Rectangle([58.0, 24.0, 63.0, 30.0], null, false);
      regionNote = 'Region: Fallback rectangle (approx. Sistan-Baluchestan)';
    }

    // 2. Data Acquisition & Check with fallback
    let src = 'CHIRPS';
    let col = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filterDate(start, end)
      .filterBounds(region)
      .select('precipitation');
    let nImgs = await col.size().getInfo();

    if (!nImgs || nImgs === 0) {
      // Fallback to ERA5-Land Daily aggregated precipitation
      src = 'ERA5-Land';
      col = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
        .filterDate(start, end)
        .filterBounds(region)
        .select('total_precipitation_sum');
      nImgs = await col.size().getInfo();
      if (!nImgs || nImgs === 0) {
        console.log(regionNote);
        console.log('CHIRPS Images: 0');
        console.log('ERA5-Land Images: 0');
        console.log('C1');
        return;
      }
    }

    // 3. Processing: Accumulate precipitation over period (mm)
    let totalMM;
    if (src === 'CHIRPS') {
      totalMM = col.sum().rename('total_mm'); // mm/day sum -> mm
    } else {
      // ERA5 total_precipitation_sum is in meters/day, sum over days -> meters
      totalMM = col.sum().multiply(1000).rename('total_mm'); // convert to mm
    }

    // Pixel count checks
    const countMeanDict = await totalMM.reduceRegion({
      reducer: ee.Reducer.count().combine({reducer2: ee.Reducer.mean(), sharedInputs: true}),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const pixCount = countMeanDict ? countMeanDict['total_mm_count'] : 0;
    const meanMM = countMeanDict ? countMeanDict['total_mm_mean'] : null;

    if (!pixCount || pixCount === 0) {
      console.log(regionNote);
      console.log(`${src} Images: ${nImgs}`);
      console.log('Valid Pixels: 0');
      console.log('C2');
      return;
    }

    // Area fraction above threshold
    const geImg = totalMM.gte(thresholdMM).rename('ge');
    const geCount = await geImg.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).get('ge').getInfo();

    const geCountNum = geCount || 0;
    const areaPct = (geCountNum / pixCount) * 100.0;

    // Additional stats for validation
    const minMax = await totalMM.reduceRegion({
      reducer: ee.Reducer.minMax(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();
    const minMM = minMax ? minMax['total_mm_min'] : null;
    const maxMM = minMax ? minMax['total_mm_max'] : null;

    // 4. Validation & Final Answer
    const invalid = (
      meanMM === null || isNaN(meanMM) ||
      areaPct < 0 || areaPct > 100 ||
      (minMM !== null && maxMM !== null && (minMM > maxMM))
    );
    if (invalid) {
      console.log(regionNote);
      console.log(`${src} Images: ${nImgs}`);
      console.log(`Pixels: ${pixCount}`);
      console.log('C3');
      return;
    }

    // Print concise evidence (<=20 lines)
    console.log(regionNote);
    console.log(`${src} Images: ${nImgs} (Period: 2020-01-08 to 2020-01-15)`);
    console.log(`Pixels: ${pixCount}`);
    console.log(`Total Precip Avg (mm): ${meanMM.toFixed(1)}`);
    console.log(`Total Precip Min/Max (mm): ${Number(minMM).toFixed(1)}/${Number(maxMM).toFixed(1)}`);
    console.log(`Area >= 76.2 mm: ${areaPct.toFixed(1)}%`);

    // Decision: "experience over 3 inches" -> any substantial area ≥ threshold.
    // Use threshold of ≥1% area to avoid single-pixel noise.
    const answer = areaPct >= 1.0 ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    // Any errors such as band name issues, memory, etc.
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
